/**
 * Convert a MIME type pattern into a case-insensitive regular expression.
 *
 * Every character is escaped for use in a regular expression, except the `*`
 * wildcard which is translated into `.*` so patterns such as
 * 'application/vnd.*+json' match 'application/vnd.api+json'.
 */
const patternToRegExp = (pattern: string): RegExp => {
  const escaped = pattern.replaceAll(/[.*+?^${}()|[\]\\]/g, (char) => (char === '*' ? '.*' : `\\${char}`))
  return new RegExp(`^${escaped}$`, 'i')
}

/**
 * Search through an array of client plugins and return the first response body
 * handler whose declared MIME types match the given MIME type.
 *
 * Matching is case-insensitive and supports wildcard glob patterns. Plugins
 * without a responseBody property are skipped. Returns undefined when no
 * handler matches.
 */
export const resolveResponseBodyHandler = (
  mimeType: string,
  plugins: ClientPlugin[],
): ResponseBodyHandler | undefined => {
  for (const plugin of plugins) {
    if (!plugin.responseBody) {
      continue
    }

    for (const handler of plugin.responseBody) {
      const isMatch = handler.mimeTypes.some((pattern) => patternToRegExp(pattern).test(mimeType))
      if (isMatch) {
        return handler
      }
    }
  }

  return undefined
}
