/**
 * Decode the buffer according to its content-type.
 *
 * When a ResponseBodyHandler with a decode function is provided, delegates to
 * that handler — passing both the buffer and the full content type string —
 * and returns its result. Otherwise falls back to default text/binary decoding.
 *
 * @returns The decoded string or Blob
 */
export const decodeBuffer = async (
  buffer: ArrayBuffer,
  contentType: string,
  pluginHandler?: ResponseBodyHandler,
): Promise<string | Blob> => {
  // Delegate to a plugin handler when it provides a decode function
  if (pluginHandler?.decode) {
    return pluginHandler.decode(buffer, contentType)
  }

  const mimeType = parseMimeType(contentType)

  // Text
  if (isTextMediaType(mimeType.essence)) {
    const decoder = new TextDecoder(mimeType.parameters.get('charset'))
    return decoder.decode(buffer)
  }

  // Binary
